function CompactRange(props:InputHTMLAttributes<HTMLInputElement>){
 const label=props["aria-label"];
 return <span className="rl-range-pair"><input {...props} type="range"/><input {...props} type="number" aria-label={label?`${label} exact value`:undefined} onChange={event=>{const value=event.currentTarget.valueAsNumber;if(!Number.isFinite(value))return;event.currentTarget.value=String(Math.max(Number(props.min),Math.min(Number(props.max),value)));props.onChange?.(event)}}/></span>;
}
